        while current_pair:
            if current_pair.key == key:
                if previous_pair:
                    previous_pair.next = current_pair.next
                else:
                    self.table[index] = current_pair.next
                return
            previous_pair = current_pair
            current_pair = current_pair.next

    def contains(self, key):
        index = self._hash(key)
        current_pair = self.table[index]
        while current_pair:
            if current_pair.key == key:
                return True
            current_pair = current_pair.next
        return False

    def rehash(self):
        new_size = self.size * 2 + 1
        new_table = Map(new_size)
        for pair in self.table:
            while pair:
                new_table.insert(pair.key, pair.value)
                pair = pair.next
        self.size = new_size
        self.table = new_table.table

    def hash_function(self):
        return self._hash

    def set_size(self, size):
        self.size = size

    def get_size(self):
        return self.size

    def get_table(self):
        return self.table

    def key_set(self):
        keys = []
        for pair in self.table:
            while pair:
                keys.append(pair.key)
                pair = pair.next
        return keys

    def value_set(self):
        values = []
        for pair in self.table:
            while pair:
                values.append(pair.value)
                pair = pair.next
        return values

    def entry_set(self):
        entries = []
        for pair in self.table:
            while pair:
                entries.append((pair.key, pair.value))
                pair = pair.next
        return entries

    def __str__(self):
        result = []
        for pair in self.table:
            while pair:
                result.append((pair.key, pair.value))
                pair = pair.next
        return str(result)

