import numpy as np

def solve(n, roads):
    if not roads or n < 2:
        return 0

    parents = [i for i in range(n)]
    ranks = [0] * n
    min_heap = [(w, u, v) for (u, v, w) in roads]
    total = 0
    def find(x):
        if parents[x] != x:
            parents[x] = find(parents[x])
        return parents[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        rank_dict = {i: r for i, r in zip(parents + ranks, range(len(parents)+len(ranks)))}
        if rank_dict[rx] < rank_dict[ry]:
            parents[rx] = ry
        else:
            parents[ry] = rx
        return True

    for w, u, v in sorted(min_heap, key=lambda x: x[0]):
        if union(u, v):
            total += w
    return total if set(len(set(parents))) == 1 else -1

def verify_inclusion(X, M, L=1e6):
    m_dim = len(M[0])
    x_dim = len(X[0])
    if x_dim != m_dim:
        raise ValueError("Dimensions of M and X do not match")

    inclusion_depths = []

    for x in X:
        points_within_l = M[np.linalg.norm(M, axis=1) <= L]
        if points_within_l.size > 0:
            distances = np.linalg.norm(points_within_l - x, axis=1)
            nearest_indices = np.argmin(distances)
            nearest_point = points_within_l[nearest_indices]
            if np.all(np.linalg.norm(nearest_point - x, axis=1) < np.linalg.norm(x - x, axis=1)):
                inclusion_depths.append(np.sum((x - nearest_point)**2))

    return np.sum(inclusion_depths)

