def silver_bars(ary):
    acc, maxlen, v, i = [], 0, 0, 0
    for elt in chain(ary, [0]):
        if elt == 0:
            if v and v >= maxlen:
                acc = acc[1:]+[[i-v, i-1]]
                maxlen, v = i-v, 0
        elif v == elt - 1:
            v += 1
        else:
            if v and v >= maxlen:
                acc = acc[1:]+[[i-v, i-1]]
                maxlen, v = i-v, 1
            else:
                v = 1
        i += 1
    return max(acc, key = len)


