    if len(s) != len(t):
        return False

    # Create a dictionary to count occurrences of each letter in s
    count_s = {}
    for letter in s:
        count_s[letter] = count_s.get(letter, 0) + 1

    # Subtract occurrences of each letter in t from the counts in count_s
    # If all counts drop to zero, t is a rearrangement of s
    for letter in t:
        if letter not in count_s:
            return False
        count_s[letter] -= 1
        if count_s[letter] < 0:
            return False

    # If we reach this point, it means every count in count_s is zero
    return True

