class BIT:
    def __init__(self, size):
        self.N = size
        self.tree = [0] * (self.N + 1)

    def lowbit(self, x):
        return x & -x

    def build(self, x):
        while x <= self.N:
            self.tree[x] += 1
            x += self.lowbit(x)

    def query(self, x):
        sums = 0
        while x:
            sums += self.tree[x]
            x -= self.lowbit(x)
        return sums

