            while i != parents[i]:
                i = parents[i]
            return i

        for w, u, v in edges:
            pu, pv = find(u), find(v)
            if pu != pv:
                parents[pv] = pu
                min_spanning_tree.append((u, v, w))
        return min_spanning_tree

    mst = kruskal(graph)
    return sum(w for _, _, w in mst)

