def dijkstra(start, end, road_graph):
    # dist[n]: geodeet distance to the node n
    dist = {}
    dist[start] = 0
    heap = []
    heapq.heappush(heap, Node(start, 0))
    # handles of vertices we have poped in the heap
    w_in_heap = {}

    while len(heap) > 0:
        vertex_node = heapq.heappop(heap)
        w_in_heap[vertex_node.vertex] = False
        if vertex_node.vertex == end:
            break
        graph = road_graph.neighbours.get(vertex_node.vertex, [])
        for neighbour, weight in graph:
            current_weight = dist.get(neighbour, float('inf'))
            other_weight = dist.get(neighbour, float('inf'))
            dist[neighbour] = min(other_weight, current_weight + weight)
            heapq.heappush(heap, Node(neighbour, dist[neighbour]))

    return dist.get(end, float('inf'))        

