def kruskal(n, edges):
    # Kruskal's algorithm to find the minimum spanning tree
    parent = list(range(n))
    rank = [1] * n
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if rank[root_x] > rank[root_y]:
            parent[root_y] = root_x
        else:
            parent[root_x] = root_y
            if rank[root_x] == rank[root_y]:
                rank[root_y] += 1

    mst_weight = 0
    edges_used = 0
    for u, v, w in sorted(edges, key=lambda x: x[2]):
        if find(u) != find(v):
            union(u, v)
            mst_weight += w
            edges_used += 1
            if edges_used == n - 1:
                break
    else:
        return -1 # Not all cities can be linked

    # Check if the MST correctly connects all cities
    path_count = [0] * n
    for u, v, w in edges:
        if find(u) == find(v):
            path_count[find(u)] += 1

    if any(count == 0 for count in path_count):
        return -1 # Not all cities are part of the MST

    return mst_weight


