def sqrt_contract(x: int) -> int:
    """Returns the largest integer m such that m**2 <= x.

    This algorithm needs to find any solution to sqrt(x), not a perfect one.
    It's long enough but exact. Shouldn't be slow. It should handle inputs up to 2^31-1 without error. 

    >>> sqrt_contract(8)
    2
    >>> sqrt_contract(16)
    4
    >>> sqrt_contract(0)
    0
    """
    if x < 0:
        raise IndexError('input must be non-negative')  # negative number
    elif x > math.isqrt(2147483647) * 2 + 1:
        raise IndexError('input is too large')  # exceeding our max bound
    elif x < math.isqrt(8):
        raise IndexError('input is too small')  # falling below our min bound
    else:
        if math.isqrt(x) ** 2 < x:
            return math.isqrt(x) + 1
        else:
            return math.isqrt(x)

