def inversion_count(nums):
    """Helper function to count inversions using merge sort."""
    if len(nums) <= 1:
        return nums, 0
    mid = len(nums) // 2
    left, inv_left = inversion_count(nums[:mid])
    right, inv_right = inversion_count(nums[mid:])
    merged, inv_merge = merge_and_count(left, right)
    total_inv = inv_left + inv_right + inv_merge
    return merged, total_inv

def merge_and_count(left, right):
    """Helper function to merge two sorted lists and count inversions."""
    result = []
    i = j = inv = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
            inv += len(left) - i
    result.extend(left[i:])
    result.extend(right[j:])
    return result, inv

