def solve(n, roads):
    import heapq

    parent = list(range(n))
    rank = [1] * n

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return False
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
        else:
            parent[v_root] = u_root
            if rank[u_root] == rank[v_root]:
                rank[u_root] += 1
        return True

    minheap = []
    for u, v, w in roads:
        heapq.heappush(minheap, (w, u, v))

    total_cost = 0
    count = 0

    while minheap and count < n - 1:
        w, u, v = heapq.heappop(minheap)
        if union(u, v):
            total_cost += w
            count += 1

    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1

    return total_cost

