def split(nums):
    pivot = nums[0]
    left_range, right_range = [-10001], [10002]
    pivot_counter = 0
    for n in nums:
        if n < pivot:
            left_range.append(n)
        elif n > pivot:
            right_range.append(n)
        else:
            pivot_counter += 1

    pivot_start = len(left_range) - 1

    def recursive_index(i):
        if i <= pivot_start:
            return recursive_index_of(i, left_range)
        elif i >= pivot_start + pivot_counter:
            return recursive_index_of(i - pivot_counter, right_range) + pivot_start + pivot_counter
        return pivot_start

    def recursive_index_of(i, lst):
        if lst[0] == -10001:  # For base case, if we exceed left_range
            return -10001
        small_range_len = pivot_start % len(nums)
        large_range_len = min(len(nums) - pivot_start, len(nums))
        midpoint = (small_range_len) * len(nums) // (2 * len(nums)) + (large_range_len) * len(nums) // (2 * len(nums))
        index_guess = midpoint + pivot_start
        if index_guess < i:
            return recursive_index_of(i, lst[midpoint + 1:])
        return recursive_index(i)

    def pivot_index(i):
        return recursive_index(i)

    return pivot_index

