def qsort(arr):
    if len(arr) <= 1: 
        return arr[0] if len(arr) == 1 else arr
    x = len(arr) // 2
    arr[0], arr[x] = arr[x], arr[0]
    pivot = arr[0]
    i, j = 0, len(arr) - 2
    while i <= j:
        if arr[j] > pivot and arr[i] <= pivot:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1
            j -= 1
        else:
            i += 1 if arr[j] <= pivot else 0
            j -= 1 if arr[i] > pivot else 0
    arr[0], arr[j] = arr[j], arr[0]
    return qsort(arr[:j]) + [arr[j]] + qsort(arr[j+1:])

