def median_of_three(nums, p, r):
    mid = (p + r) // 2
    if nums[p] > nums[mid]:
        nums[p], nums[mid] = nums[mid], nums[p]
    if nums[p] > nums[r]:
        nums[p], nums[r] = nums[r], nums[p]
    if nums[mid] > nums[r]:
        nums[mid], nums[r] = nums[r], nums[mid]
    nums[mid], nums[r - 1] = nums[r - 1], nums[mid]
    return nums, r - 1

def quickselect(nums, k):
    p, r = 0, len(nums) - 1
    while p < r:
        nums, q = median_of_three(nums, p, r)
        q = partition_quicksort(nums, p, r)
        if k < q:
            r = q - 1
        elif k > q:
            p = q + 1
        else:
            return nums[q]
    return nums[p]

