def quickselect(nums: list[int], k: int, start: int = 0, end: int = float('inf')) -> int:
    end = len(nums) if end == float('inf') else end
    count_of_larger = len(nums) - end

    initial_num = sorted(nums[start:end])[0]

    for i in range(start, end - count_of_larger):
        current_num = nums[i]

        while True:
            if nums[i + count_of_larger - 1] <= current_num <= initial_num:
                nums[i], nums[i + count_of_larger - 1] = nums[i + count_of_larger - 1], nums[i]
                break
            if current_num <= initial_num:
                nums[i], nums[start] = nums[start], nums[i]
                break
            else:
                current_num = nums[start]
                nums[i], nums[start] = nums[start], nums[i]

    if start == end - count_of_larger:
        return nums[start]
    else:
        if k > count_of_larger:
            return quickselect(nums, k - count_of_larger, start + 1, end)
        else:
            return quickselect(nums, k, start, start + count_of_larger - 1)


