class Solution:
    def solve(self, board: List[List[str]]) -> None:
        if not board:
            return
        nr, nc = len(board), len(board[0])
        def capture(r, c):
            if r < 0 or c < 0 or r == nr or c == nc or board[r][c] != 'O':
                return
            board[r][c] = "T"
            # Exclude all the 0s in the circumference
            capture(r + 1, c)
            capture(r - 1, c)
            capture(r, c + 1)
            capture(r, c - 1)
        # 1. Capture unsurrounded regions (<- CS Adjacent)
        for r in range(nr):
            for c in range(nc):
                if board[r][c] == 'O' and (r in [0, nr - 1] or c in [0, nc - 1]):
                    capture(r, c)
        # 2. Capture surrounded regions
        for r in range(nr):
            for c in range(nc):
                if board[r][c] == "O":
                    board[r][c] = "X"
        # 3. Uncapture unsurrounded regions
        for r in range(nr):
            for c in range(nc):
                if board[r][c] == "T":
                    board[r][c] = "O"

