def binary_search(lst, val):
    start, end = 0, len(lst) - 1
    while start <= end:
        mid = (start + end) // 2
        if lst[mid] > val:
            end = mid - 1
        elif lst[mid] < val:
            start = mid + 1
        else:
            return True
    return False


