def min_pours(jug_a: int, jug_b: int, target: int) -> int:
    """
    Returns the minimum number of pours necessary to measure out target liters
    using the two given jugs, without using set data types.

    Each full pour from one jug into another counts as one "pour".
    Solution must exist with k <= 1000 pours.
    """
    def dfs(remaining, jug_a_filled, jug_b_filled, count):
        if remaining == target:
            return count
        if jug_a_filled > 0:
            new_remaining = jug_a_filled - min(jug_a_filled, remaining)
            new_jug_a_filled = max(0, jug_a_filled - remaining)
            if new_remaining == target or new_jug_a_filled == target:
                return min(count + 1, dfs(remaining, new_jug_a_filled, jug_b_filled, count + 1))
            if new_remaining > 0:
                return dfs(new_remaining, new_jug_a_filled, jug_b_filled, count + 1)
        if jug_b_filled > 0:
            new_remaining = jug_b_filled - min(jug_b_filled, remaining)
            new_jug_b_filled = max(0, jug_b_filled - remaining)
            if new_remaining == target or new_jug_b_filled == target:
                return min(count + 1, dfs(remaining, jug_a_filled, new_jug_b_filled, count + 1))
            if new_remaining > 0:
                return dfs(new_remaining, jug_a_filled, new_jug_b_filled, count + 1)
        return 1001

    return dfs(target, 0, 0, 0)

