def solve_helper(nums):
    i, j = 0, len(nums) - 1
    while i < j:
        m = (i + j) // 2
        cnt = sum(1 for x in nums if x <= m)
        if cnt <= m:
            i = m + 1
        else:
            j = m
    return i

