def solve(nums, k):
    # Use a max-heap of size k to keep track of the k smallest elements
    heap = []
    for num in nums:
        if len(heap) < k:
            heapq.heappush(heap, -num)
        else:
            if num < -heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, -num)
    return -heap[0]

