def solve(nums, k):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1
    sorted_scores = sorted(counts.keys())
    for score in sorted_scores:
        if k <= counts[score]:
            return score
        k -= counts[score]
    return -1

def solve(nums, k):
    def count_less_equal(x):
        cnt = 0
        for num in nums:
            if num <= x:
                cnt += 1
            if cnt >= k:
                return True
        return cnt >= k

    left, right = min(nums), max(nums)
    while left < right:
        mid = (left + right) // 2
        if count_less_equal(mid):
            right = mid
        else:
            left = mid + 1
    return left

