def natural_sum(n, memo={}):
    if n < 1 or not isinstance(n, int):
        return "Invalid input: n must be a positive integer"
    if n == 1:
        return 1
    if n in memo:
        return memo[n]
    result = n + natural_sum(n - 1, memo)
    memo[n] = result
    return result

