from collections import Counter

def solve(nums, k):
    counts = Counter(nums)
    sorted_counts = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    result = []
    for i in range(len(sorted_counts)):
        if i < k:
            result.append(sorted_counts[i][0])
        else:
            break
    return result

