def solve(nums, k):
    counts = Counter(nums)
    sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    selected = set()
    current_freq = None
    count = 0
    for num, freq in sorted_counts:
        if current_freq is None or freq != current_freq:
            if current_freq is not None:
                count += 1
            current_freq = freq
        if count == k:
            selected.add(num)
    return list(selected)

